import {readFile,writeFile,rename,symlink} from 'node:fs/promises';
import {resolve} from 'node:path';
import {Persistence,ReplaySession} from '@tileset/persistence';
import assert from 'node:assert/strict';
const conf=JSON.parse(await readFile(process.argv[2],'utf8')),resources=JSON.parse(await readFile('apps/api/dist/resources/studio.json','utf8'));const store=new Persistence(conf.database,conf.assets,resources.profile), output={source:resources.context.commit,ordinary:false,warmSourceAncestorBoundary:'pending',mismatchedSessionLifetime:'pending'};
try{
 const project=await store.db.project.findFirstOrThrow({where:{successfulBuildId:{not:null}}});
 await store.gate.write(async lease=>{
  const session=new ReplaySession(lease.signal);await store.loadArchives(project.id,session);output.ordinary=true;
  const objects=resolve(conf.assets,'objects'),saved=objects+'.warm-boundary-original';await rename(objects,saved);
  try{await symlink(saved,objects);await assert.rejects(()=>store.loadArchives(project.id,session));output.warmSourceAncestorBoundary='REJECTED_REAL_EXISTING_ANCESTOR_SYMLINK';}
  finally{await rename(objects,objects+'.warm-boundary-rejected-link');await rename(saved,objects);}
  const replay=await store.loadArchives(project.id,session);assert(replay.records.length>0);output.recoverySameOwnedSources=true;
  const build=await store.db.build.findUniqueOrThrow({where:{id:project.successfulBuildId}});await assert.rejects(()=>store.prepareBuild(project.id,build.packId,build.projectSnapshotId,[],resources.context,new ReplaySession()),/Replay session lifetime differs/);output.mismatchedSessionLifetime='REJECTED_OTHER_SIGNAL_UNDER_CURRENT_LEASE';
 },'warm-boundary-control');
}finally{await store.close();await writeFile(process.argv[3],JSON.stringify(output,null,2)+'\n');}
console.log(JSON.stringify(output));
